import { useState } from "react";
import { Pressable, Text, type StyleProp, type ViewStyle } from "react-native";
import { StyleSheet } from "react-native-unistyles";

export type ActionButtonKind =
  "primary" | "secondary" | "destructive" | "positive";

type ActionButtonProps = {
  label: string;
  onPress: () => void;
  kind?: ActionButtonKind;
  accessibilityLabel?: string;
  testID?: string;
  style?: StyleProp<ViewStyle>;
};

/**
 * The app's one tappable control. Every button-shaped surface — grading a
 * card, confirming a form, a destructive action — renders this rather than
 * its own `Pressable`, so the minimum target size and the focus ring are
 * enforced in one place instead of re-implemented at each call site.
 */
export function ActionButton({
  label,
  onPress,
  kind = "primary",
  accessibilityLabel,
  testID,
  style,
}: ActionButtonProps) {
  const [isFocused, setIsFocused] = useState(false);

  styles.useVariants({ kind, focused: isFocused });

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel ?? label}
      testID={testID}
      onPress={onPress}
      onFocus={() => setIsFocused(true)}
      onBlur={() => setIsFocused(false)}
      style={[styles.button, style]}
    >
      <Text style={styles.label}>{label}</Text>
    </Pressable>
  );
}

const styles = StyleSheet.create((theme) => ({
  button: {
    minWidth: theme.sizing.minTouchTarget,
    minHeight: theme.sizing.minTouchTarget,
    alignItems: "center",
    justifyContent: "center",
    borderRadius: theme.radius.md,
    borderWidth: 2,
    borderColor: "transparent",
    paddingHorizontal: theme.spacing(2),
    variants: {
      kind: {
        primary: { backgroundColor: theme.colors.accent },
        secondary: {
          backgroundColor: theme.colors.surface,
          borderColor: theme.colors.border,
        },
        destructive: { backgroundColor: theme.colors.negative },
        positive: { backgroundColor: theme.colors.positive },
        default: { backgroundColor: theme.colors.accent },
      },
      // Declared after `kind` so a focused button's border colour wins over
      // `secondary`'s — variant groups apply in this object's key order.
      focused: {
        true: { borderColor: theme.colors.focusRing },
        false: {},
        default: {},
      },
    },
  },
  label: {
    ...theme.typography.label,
    variants: {
      kind: {
        primary: { color: theme.colors.onAccent },
        secondary: { color: theme.colors.text },
        destructive: { color: theme.colors.onAccent },
        positive: { color: theme.colors.onAccent },
        default: { color: theme.colors.onAccent },
      },
    },
  },
}));

import type { PropsWithChildren } from "react";
import { ScrollView, View } from "react-native";
import { StyleSheet } from "react-native-unistyles";

type ScreenProps = PropsWithChildren<{
  /** Wraps the content in a ScrollView, for forms that can outgrow the viewport. */
  scrollable?: boolean;
}>;

/**
 * Wraps a route's content in the device safe area, paints the theme's
 * background colour behind it, and applies the app's standard content
 * padding. Every screen the router renders uses this rather than laying out
 * against the raw window.
 *
 * The safe area comes from Unistyles' own mini runtime rather than a
 * separate safe-area context hook, so it recomputes on the same path as the
 * rest of the stylesheet. Only the horizontal insets are combined with this
 * screen's own gutter (`Math.max`, so a device with no notch still gets the
 * design's spacing) — the vertical insets are applied as-is, because
 * `content` below layers its own vertical breathing room on top of them
 * rather than folding it into the same value.
 */
export function Screen({ children, scrollable = false }: ScreenProps) {
  return (
    <View style={styles.screen}>
      {scrollable ? (
        <ScrollView
          contentContainerStyle={styles.content}
          keyboardShouldPersistTaps="handled"
        >
          {children}
        </ScrollView>
      ) : (
        <View style={styles.content}>{children}</View>
      )}
    </View>
  );
}

const styles = StyleSheet.create((theme, rt) => ({
  screen: {
    flex: 1,
    backgroundColor: theme.colors.background,
    paddingTop: rt.insets.top,
    paddingBottom: rt.insets.bottom,
    paddingStart: Math.max(rt.insets.left, theme.spacing(2)),
    paddingEnd: Math.max(rt.insets.right, theme.spacing(2)),
  },
  content: {
    flexGrow: 1,
    paddingVertical: theme.spacing(2),
    gap: theme.spacing(2),
  },
}));

