3	 * whatever the URL held, including an empty string, a repeated segment as
4	 * an array, or nothing at all. Normalizing it here, before any lookup
5	 * trusts it, is what lets a screen render a not-found state instead of
6	 * chasing a malformed id into a repository call.
7	 */
8	export function normalizeDeckId(
9	  raw: string | string[] | undefined,
10	): string | null {
11	  if (typeof raw !== "string") {
12	    return null;
13	  }
14	
15	  const trimmed = raw.trim();
16	  return trimmed.length > 0 ? trimmed : null;
17	}
